pps, bots = [], []delay = 0.5custom_nc_delays = {}# --- GEN2CUDAI HIGH-SPEED AUTO-SPEED STATES ---NORMAL_DELAY   = 0.05  # Optimized for Max SpeedBOOST_DELAY    = 0.01  # Instant execution on kickbackBOOST_DURATION = 60     CHECK_INTERVAL = 3      _boost_state = {}_last_set_title = {}# --- NCTYM/DOLLAR REPLICA HIGH SPEED STATE CONFIG ---COPY_NORMAL_DELAY = 0.05COPY_BOOST_DELAY  = 0.01COPY_CHECK_INT    = 1# GOD LEVEL OPTIMIZATION STATE FOR ALL OTHER NC MODESGOD_SPEED_DELAY = 0.05 # Reduced lag bottleneck# New State for Auto Reactionreact_emoji = Nonereact_target_user_id = None# Global storage for the saved game over picture/video file IDSAVED_OVER_PHOTO_ID = NoneSAVED_OVER_VIDEO_ID = None# Global storage for the saved menu picture/video file IDSAVED_MENU_PHOTO_ID = NoneSAVED_MENU_VIDEO_ID = None# --- NEW EXCLUSIVE PFP STATE PARAMETERS ---lpfp_file_id = {}lpfp_active_chats = set()# --- TARGET COMMAND SLIDE GLOBAL DICTIONARIES ---sl_target_usernames = {}sl_last_msg_ids = {}sl_active_counters = {}logging.basicConfig(level=logging.INFO)# ---------------------------# FONT STYLIZER FOR GEN2CUDAI# ---------------------------_SMALL_CAPS = {    'a': 'ᴀ', 'b': 'ʙ', 'c': 'ᴄ', 'd': 'ᴅ', 'e': 'ᴇ',    'f': 'ғ', 'g': 'ɢ', 'h': 'ʜ', 'i': 'ɪ', 'j': 'ᴊ',    'k': 'ᴋ', 'l': 'ʟ', 'm': 'ᴍ', 'n': 'ɴ', 'o': 'ᴏ',    'p': 'ᴘ', 'q': 'q', 'r': 'ʀ', 's': 'ꜱ', 't': 'ᴛ',    'u': 'ᴜ', 'v': 'ᴠ', 'w': 'ᴡ', 'x': 'x', 'y': 'ʏ',    'z': 'ᴢ',}def stylize_name(text: str) -> str:    result = []    pos = 0    for char in text:        if char.isalpha():            if pos % 3 == 0:                result.append(char.upper())            else:                result.append(_SMALL_CAPS.get(char.lower(), char.lower()))            pos += 1        else:            result.append(char)    return "".join(result)# ---------------------------# DECORATORS# ---------------------------def only_sudo(func):    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):        if not update.effective_user:            return        uid = update.effective_user.id        if uid == OWNER_ID or uid in SUDO_USERS or uid in [b.id for b in bots]:            return await func(update, context)        return await update.message.reply_text(UNAUTH_OWNER_MSG)    return wrapperdef only_owner(func):    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):        if not update.effective_user:            return        uid = update.effective_user.id        if uid == OWNER_ID:            return await func(update, context)        return await update.message.reply_text(UNAUTH_OWNER_MSG)    return wrapper# -------------------------------------------------------------# 🛡️ FLOOD-SAFE ANTI-BAN CORE ENGINE (SUDO ENGINE RE-MODDED)# -------------------------------------------------------------async def safe_set_title(bot, chat_id: int, text: str) -> bool:    try:        await asyncio.wait_for(bot.set_chat_title(chat_id, text), timeout=3)        return True    except RetryAfter as e:        await asyncio.sleep(e.retry_after) # Hard sync without adding dynamic random lag        return False    except (TimedOut, NetworkError):        return False    except asyncio.CancelledError:        raise    except Exception as e:        err = str(e).lower()        if "flood" in err or "too many" in err:            await asyncio.sleep(1.0)        else:            await asyncio.sleep(0.05)        return Falseasync def safe_reply(update: Update, text: str, parse_mode=None):    try:        return await update.message.reply_text(text, parse_mode=parse_mode)    except Exception:        passasync def god_level_set_title(bot, chat_id: int, text: str) -> bool:    try:        await bot.set_chat_title(chat_id, text)        return True    except RetryAfter as e:        await asyncio.sleep(e.retry_after)        return False    except Exception:        await asyncio.sleep(0.05)        return Falsedef _current_delay(chat_id: int) -> float:    if "gen2cudai" in custom_nc_delays.get(chat_id, {}):        return custom_nc_delays[chat_id]["gen2cudai"]    if _boost_state.get(chat_id, 0) > 0:        return BOOST_DELAY    return NORMAL_DELAYdef _trigger_boost(chat_id: int):    _boost_state[chat_id] = BOOST_DURATIONdef _tick_boost(chat_id: int):    if _boost_state.get(chat_id, 0) > 0:        _boost_state[chat_id] -= 1# ---------------------------# OPTIMIZED ENGINE INDEPENDENT LOOPS# ---------------------------async def gen2cudai_independent_loop(bot, chat_id: int, target: str, bot_index: int):    await asyncio.sleep(bot_index * 0.05) # Parallel spawn offset reduced    i = bot_index    check_counter = 0    while True:        try:            pattern = GEN2CUDAI_TEXTS[i % len(GEN2CUDAI_TEXTS)]            text = pattern.replace("{target}", target)            check_counter += 1            if check_counter >= CHECK_INTERVAL:                check_counter = 0                try:                    chat_info = await asyncio.wait_for(bot.get_chat(chat_id), timeout=2)                    actual_title = chat_info.title or ""                    expected = _last_set_title.get(chat_id, "")                    if expected and actual_title != expected:                        _trigger_boost(chat_id)                except asyncio.CancelledError:                    raise                except Exception:                    pass            success = await safe_set_title(bot, chat_id, text)            if success:                _last_set_title[chat_id] = text                _tick_boost(chat_id)                i += 1            await asyncio.sleep(_current_delay(chat_id))        except asyncio.CancelledError:            raise        except Exception:            await asyncio.sleep(0.1)async def pyrogram_style_newgencudai_loop(bot, chat_id: int, base: str, bot_index: int):    await asyncio.sleep(bot_index * 0.05)    while True:        try:            for index, raw_text in enumerate(NEWGENCUDAI_TEXTS):                text = raw_text.format(base) if "{}" in raw_text else f"{base} {raw_text}"                try:                    await bot.set_chat_title(chat_id, text)                    current_delay = custom_nc_delays.get(chat_id, {}).get("newgencudai", 0.05)                    await asyncio.sleep(current_delay)                  except RetryAfter as e:                    await asyncio.sleep(e.retry_after)                except asyncio.CancelledError:                    raise                except Exception:                    await asyncio.sleep(0.1)        except asyncio.CancelledError:            raise        except Exception:            await asyncio.sleep(0.5)async def copy_replica_independent_loop(bot, chat_id: int, base: str, mode: str, bot_index: int):    await asyncio.sleep(bot_index * 0.05)    i = bot_index    check_counter = 0    current_engine_delay = COPY_NORMAL_DELAY        while True:        try:            if mode == "adominate":                raw_text = ADOMINATE_TEXTS[i % len(ADOMINATE_TEXTS)]                text = raw_text.format(base) if "{}" in raw_text else f"{base} {raw_text}"            elif mode == "agod":                raw_text = AGOD_TEXTS[i % len(AGOD_TEXTS)]                text = raw_text.format(base) if "{}" in raw_text else f"{base} {raw_text}"            else:                text = f"{base}"            check_counter += 1            if check_counter >= COPY_CHECK_INT:                check_counter = 0                try:                    chat_info = await asyncio.wait_for(bot.get_chat(chat_id), timeout=2)                    actual_title = chat_info.title or ""                    expected = _last_set_title.get(chat_id, "")                    if expected and actual_title != expected:                        current_engine_delay = COPY_BOOST_DELAY                    else:                        current_engine_delay = COPY_NORMAL_DELAY                except asyncio.CancelledError:                    raise                except Exception:                    pass            success = await god_level_set_title(bot, chat_id, text)            if success:                _last_set_title[chat_id] = text                i += 1            if mode in custom_nc_delays.get(chat_id, {}):                await asyncio.sleep(custom_nc_delays[chat_id][mode])            else:                await asyncio.sleep(current_engine_delay)        except asyncio.CancelledError:            raise        except Exception:            await asyncio.sleep(0.1)async def hyper_nc_independent_loop(bot, chat_id: int, base: str, mode: str, bot_index: int):    await asyncio.sleep(bot_index * 0.05)      i = bot_index    while True:        try:            if mode == "raid":                text = f"{base} {RAID_TEXTS[i % len(RAID_TEXTS)]}"            elif mode == "emoji":                text = f"{base} {NCEMO_EMOJIS[i % len(NCEMO_EMOJIS)]}"            elif mode == "nfnc":                raw_text = NFNC_TEXTS[i % len(NFNC_TEXTS)]                text = raw_text.format(base) if "{}" in raw_text else f"{base} {raw_text}"            elif mode == "tnc":                current_time = time.time() + 19800                ist_time = f"{int(current_time % 86400 // 3600):02d}:{int(current_time % 3600 // 60):02d}:{int(current_time % 60):02d}"                rand_emo = random.choice(NCEMO_EMOJIS)                text = f"{base} {rand_emo} [{ist_time}]"            elif mode == "fstnc":                rand_emo = random.choice(NCEMO_EMOJIS)                text = f"{base} {rand_emo}"            elif mode == "sequential":                raw_text = SNC_TEXTS[i % len(SNC_TEXTS)]                text = raw_text.format(base) if "{}" in raw_text else f"{base} {raw_text}"            elif mode == "cute":                raw_text = cute_TEXTS[i % len(cute_TEXTS)]                text = raw_text.format(base) if "{}" in raw_text else f"{base} {raw_text}"            elif mode == "secync":                raw_text = SECYNC_TEXTS[i % len(SECYNC_TEXTS)]                text = raw_text.format(base) if "{}" in raw_text else f"{base} {raw_text}"            else:                text = f"{base} {NCEMO_EMOJIS[i % len(NCEMO_EMOJIS)]}"            success = await god_level_set_title(bot, chat_id, text)            if success:                i += 1            if mode in custom_nc_delays.get(chat_id, {}):                await asyncio.sleep(custom_nc_delays[chat_id][mode])            elif mode == "cute":                await asyncio.sleep(0.05)            elif mode == "secync":                await asyncio.sleep(0.05)            else:                await asyncio.sleep(GOD_SPEED_DELAY)        except asyncio.CancelledError:            raise        except Exception:            await asyncio.sleep(0.1)# ---------------------------# SPAM LOOP FUNCTION (STANDALONE UNTOUCHED)# ---------------------------async def bot_loop(bot, chat_id, base, mode):    while True:        try:            if mode == "spam":                await bot.send_message(chat_id, base)                await asyncio.sleep(delay)        except Exception:            await asyncio.sleep(1)# ---------------------------# EXCLUSIVE FSPAM ENGINE LOOP (STANDALONE UNTOUCHED)# ------